// SADEEM — v11.34 — the 145 CORE TOOL DEFINITIONS, in their own file.
// (Was 118 at the v11.12 split; the count is regenerated by
//  scripts/gen-tool-inventory.mjs after every addition — never guessed.
//  The honest count is 145 — NOT 147.)
//
// tools.ts had grown to ~11.2k lines with the definitions (pure data) and the
// executors (logic) interleaved; the founder asked for an architecturally
// precise split so both humans and AI navigators can find the tool surface
// instantly. This file holds ONLY the definitions (name/description/schema).
// executeTool + every executor remain in tools.ts, which re-exports CORE_DEFS
// so all existing imports, test bundles and scripts/gen-tool-inventory.mjs
// keep working unchanged.
//
// v11.34 — EVERY tool here carries a stable `profile` tag (core/workflow/
// advanced/desktop/web). The tag is a LABEL for a focused per-turn VIEW; it is
// NOT a permission gate and never removes a tool or an executor. See the
// profile section at the bottom of this file + src/lib/modes.ts.
//
// NOTE: READ_DEFAULT_LIMIT is duplicated here (description text only) — the
// executor-side constant lives in tools.ts; keep the two in sync.
import type { ToolDef } from './providers';
import { rosterLine } from './agents';
import type { MCPServerConfig, MCPToolInfo } from '../../shared/types';

const READ_DEFAULT_LIMIT = 2000;

const obj = (
  properties: Record<string, unknown>,
  required: string[],
): Record<string, unknown> => ({
  type: 'object',
  properties,
  required,
  additionalProperties: false,
});

// ============================================================
// v11.34 — PER-TOOL PROFILE TAGS (a VIEW, never a capability gate)
// ------------------------------------------------------------
// Every CORE_DEF below carries one of these stable tags. They group the 145
// tools into human-sized families so a weak model can be shown a FOCUSED
// subset per turn while `full` still advertises all 145. They do NOT control
// dispatch: executeTool() resolves the FULL registry regardless of what the
// model was shown, so a tool from ANY tag (or hidden by 'balanced') still
// executes the moment the model names it.
// ============================================================
/** Stable per-tool family tag. 'mcp' is assigned to runtime MCP defs. */
export type ToolCategory = 'core' | 'workflow' | 'advanced' | 'desktop' | 'web' | 'mcp';

/** A ToolDef that carries its per-tool profile tag (core defs always do). */
export type TaggedToolDef = ToolDef & { profile?: ToolCategory };

// Let the per-tool tag live ON ToolDef without touching providers.ts or the
// inventory generator (which parses the literal `const CORE_DEFS: ToolDef[]`).
// Type-only: erased at runtime, zero effect on the bundled defs.
declare module './providers' {
  interface ToolDef {
    profile?: ToolCategory;
  }
}

/** All category tags, in the order the Composer/UI advertises them. */
export const TOOL_CATEGORIES: readonly ToolCategory[] = ['core', 'workflow', 'advanced', 'desktop', 'web', 'mcp'];

