// v11.34 — TOOL PROFILES = A PER-TURN VIEW, NEVER A CAPABILITY CUT
// ------------------------------------------------------------
// The founder's complaint: "a strong model (e.g. Claude 5.5) uses the tools
// beautifully but a weak one drowns in 145 tool defs (~103KB)". The honest
// fix is NOT to delete tools. EVERY one of the 145 defs + executors always
// exists; only the `tools[]` array ADVERTISED in a given turn changes.
//
// Two layers, one rule — "profiles only change what the model SEES":
//   1. LEGACY scopes (kept 100% backward-compatible):
//        essential → ~40 core tools (v1118 subset proof relies on this)
//        balanced  → default; hides only the deepest ADVANCED_TOOL_NAMES
//        full      → ALL 145 core tools (+ any discovered MCP tools)
//   2. PER-TOOL CATEGORY views (the new stable `profile` tag on every def):
//        core      → files/edit/run/search/code-intel/LSP/preview (~43)
//        workflow  → plan/memory/checkpoint/data/git/verify (~47)
//        advanced  → debug/notebook/docs/media/image tooling (~24)
//        desktop   → screen, device, clipboard, notifications (~8)
//        web       → search/fetch/download + browser automation (~23)
//        mcp       → MCP tools discovered at runtime
//
// CRITICAL: a profile NEVER refuses a call. executeTool() resolves against
// getToolDefs([], 'full') — so a tool hidden from the advertised view still
// executes by its exact name. Switching a weak model to a focused view loses
// ZERO capability; switching back to 'full' restores the complete surface.
// ============================================================

/** All selectable profiles: legacy scopes + the six per-tool category views. */
export type ToolProfile = 'essential' | 'balanced' | 'full' | ToolCategory;

/** Every selectable profile value (single source of truth for UI/tests). */
export const TOOL_PROFILES: readonly ToolProfile[] = [
  'balanced', 'core', 'workflow', 'advanced', 'desktop', 'web', 'mcp', 'essential', 'full',
];

/**
 * The stable tag of a def. Core defs carry it inline; runtime MCP defs fall
 * back to 'mcp' (they are built in tools.ts, outside this file).
 */
export function profileOf(def: ToolDef): ToolCategory {
  const tagged = def as TaggedToolDef;
  if (tagged.profile) return tagged.profile;
  return def.kind === 'mcp' ? 'mcp' : 'core';
}

/** True when `def` is advertised in a per-tool CATEGORY view. */
function inCategoryView(def: ToolDef, category: ToolCategory): boolean {
  // MCP tools are never hidden from any view; the 'mcp' view is exactly them.
  if (def.kind === 'mcp' || profileOf(def) === 'mcp') return true;
  return profileOf(def) === category;
}

/** The ~30 core tools every agent needs. Everything else is "advanced". */
export const ESSENTIAL_TOOL_NAMES: ReadonlySet<string> = new Set([
  // files
  'list_dir', 'read_file', 'read_image', 'write_file', 'edit_file', 'multi_edit', 'multi_file_edit',
  'move_path', 'delete_path', 'glob_files', 'search_files', 'fs_browse', 'workspace_map',
  // execution / preview
  'run_command', 'run_background', 'process_output', 'stop_process', 'preview', 'preview_screenshot',
  // search & code intel (lightweight)
  'code_search', 'find_refs', 'symbol_outline', 'repo_map',
  // planning / tracking / delegation
  'todo_write', 'propose_plan', 'task', 'remember', 'use_skill',
  // checkpoints / verify
  'checkpoint_save', 'checkpoint_list', 'checkpoint_restore', 'test_run', 'review_diff',
  // web + real downloads (the founder's #1 complaint: "cannot download")
  'web_search', 'web_fetch', 'web_download',
  // discoverability + LSP language matrix (so a weak model SEES these families)
  'tool_help', 'lsp_languages',
  // documents / images (common deliverables)
  'make_document', 'image_generate',
]);

/**
 * Deep specialist tools hidden from the 'balanced' profile (but STILL fully
 * executable — a model can call them by exact name, and 'full' advertises
 * them again). These are the tools most likely to overwhelm a weak model.
 */
export const ADVANCED_TOOL_NAMES: ReadonlySet<string> = new Set([
  // v11.15 — LSP is NO LONGER hidden from 'balanced': the founder explicitly
  // asked for LSP across languages, and a hidden tool is a tool the model
  // cannot use. lsp_languages (essential) is the discoverable entry point and
  // the six lsp_* executors are now advertised in balanced + full.
  // v11.16 — desktop_control is NO LONGER hidden from 'balanced' either: the
  // founder's core complaint is "the AI cannot use my device". A tool that is
  // only in ADVANCED is invisible to the DEFAULT 'balanced' profile, so the
  // model can never call it. Device control is approval-gated at execution,
  // so advertising it is safe — it stays fully gated. media_ffmpeg remains a
  // deep specialist (hidden from balanced, still executable by exact name).
  'debug_start', 'debug_state', 'debug_eval', 'debug_step', 'debug_stop',
  'notebook_read', 'notebook_edit_cell', 'notebook_run',
  'media_ffmpeg',
  'pdf_make', 'pptx_make', 'docx_make', 'xlsx_make', 'export_project', 'diagnose_preview',
  'browser_download', 'browser_console', 'browser_console_eval', 'browser_pdf',
  // v11.18 audit: removed 6 PHANTOM names that matched no real def and were
  // silently doing nothing (csv_tool, base64_tool, regex_tool, diff_tool,
  // color_tool, url_codec). Their real counterparts (csv_read/csv_write,
  // encode_base64/decode_base64, regex_test, diff_files, color_convert,
  // url_encode/url_decode) stay advertised in BALANCED — hiding them would be
  // the opposite of the founder's "the AI cannot use the tools it needs".
  'pdf_read', 'hash_file', 'text_stats',
  'markdown_outline', 'json_format', 'image_search',
]);

/**
 * Return the ADVERTISED subset for a profile. This is a pure VIEW over `defs`:
 * it never mutates the registry and never disables an executor. The engine
 * still dispatches every tool by exact name through executeTool(), which calls
 * getToolDefs([], 'full') — so a tool excluded here remains fully callable.
 *
 * MCP defs are kept in every view (they are opt-in gated at execution, not by
 * the profile). The legacy essential/balanced/full behaviour is unchanged.
 */
export function defsForProfile(defs: ToolDef[], profile: ToolProfile): ToolDef[] {
  if (profile === 'full') return defs;
  if (profile === 'essential') return defs.filter((d) => d.kind === 'mcp' || ESSENTIAL_TOOL_NAMES.has(d.name));
  if (profile === 'balanced') return defs.filter((d) => d.kind === 'mcp' || !ADVANCED_TOOL_NAMES.has(d.name));
  // New per-tool category views — a focused, human-sized subset.
  return defs.filter((d) => inCategoryView(d, profile));
}

// ============================================================
// v11.35 — THE FULL CAPABILITY UNION (NEVER A CAPABILITY CUT)
//
// The 145 CORE_DEFS are the stable source of truth for gen-tool-inventory.
// At runtime the real capability set is the UNION of:
//   1. the 145 core defs,
//   2. runtime MCP defs (mcp__<server>__<tool>), and
//   3. provider-advertised / provider-native tools discovered this session
//      (see providers.ts registerProviderTool / makeNativeToolDef).
// A profile only chooses which slice of that union is ADVERTISED per turn —
// it never deletes a def or disables an executor. This pure helper builds the
// union with last-writer-wins on name (a dynamically re-advertised tool may
// refine its schema) and, like defsForProfile, applies NO fixed-size slice.
// ============================================================

/**
 * Merge runtime/provider defs into the registry without dropping any core def.
 * `extras` wins on name collision so a freshly advertised schema is honoured.
 */
export function fullCapabilityUnion(defs: ToolDef[], extras: readonly ToolDef[] = []): ToolDef[] {
  const byName = new Map<string, ToolDef>();
  for (const d of defs) byName.set(d.name, d);
  for (const d of extras) byName.set(d.name, d);
  return [...byName.values()];
}

/**
 * Advertise one turn's view: the profile slice of `defs` PLUS every provider /
 * MCP extra (extras are opt-in gated at execution, never hidden by a profile).
 * The returned array is a strict superset of the profile view — no truncation.
 */
export function advertisedWithExtras(
  defs: ToolDef[],
  profile: ToolProfile,
  extras: readonly ToolDef[] = [],
): ToolDef[] {
  return fullCapabilityUnion(defsForProfile(defs, profile), extras);
}

// ============================================================
// v11.36 — MCP TOOL DEFS: canonical, lossless, honest
// ------------------------------------------------------------
// FOUNDER: "not every MCP works — I once asked it to use Blender (an
// MCP server) and it couldn't." End-to-end audit (docs/MCP-TOOLS-
// V1136.md): the RUNTIME builder already lives in tools.ts
// (getToolDefs, ~line 1317) and does NOT truncate — every tool of
// every connected server becomes a def. The real breakages are:
//   1. engine.ts:1784-1818 seeds `enabledMcp` ONLY from the SYNC
//      last-good cache; a configured + connected server that has
//      never been discovered in this process has NO defs in the
//      FIRST provider request (the fire-and-forget probe lands
//      after the tool list was already built).
//   2. engine.ts:1152-1177 `mcpOptInVerdict` only recognises an
//      EXPLICIT server name when the tool resolved to that server
//      (`info` non-null). For a cold/unknown server `info` is null
//      and "use blender" (no literal word "mcp") does NOT opt in —
//      so the founder's explicit request still hits a per-call gate.
// Both live in engine.ts (owned by another agent) → HANDOFF there.
//
// THIS section is the canonical, dependency-light DEFINITION of an
// MCP tool def and is intentionally lossless: every tool of every
// connected server gets a real def (name / description / JSON-Schema
// parameters), dispatch is by the EXACT emitted name, and a missing
// server produces an HONEST "not connected" error — never a silent
// drop. tools.ts getToolDefs() can delegate here (one-line handoff);
// until then tests/v1136-mcp-tools.test.mjs exercises this builder
// directly AND drives the real tools.ts dispatch path.
//
// NOTE: names use template literals on purpose — the v1134 inventory
// test parses `name: '...'` lines and must keep counting exactly 145
// CORE defs. Runtime MCP defs are NOT core defs.
// ============================================================

/** One connected server + the FULL tool list it advertised (no slice). */
export interface McpServerToolSource {
  server: MCPServerConfig;
  tools: readonly MCPToolInfo[];
}

/** Slug mirrors tools.ts `slugMcpName` and mcp.ts `slugMcpNameLocal`. */
export function slugMcpToolName(part: string): string {
  return (
    String(part ?? '')
      .toLowerCase()
      .replace(/[^a-z0-9_-]+/g, '_')
      .replace(/^_+|_+$/g, '') || 'mcp'
  );
}

function jsonSchemaObject(v: unknown): Record<string, unknown> {
  return v && typeof v === 'object' && !Array.isArray(v)
    ? (v as Record<string, unknown>)
    : { type: 'object' };
}

/**
 * Build a REAL def for EVERY tool from EVERY connected MCP server.
 * No `slice`, no first-N, no "only the first server" — a server that
 * advertises 3 tools yields exactly 3 defs; a server with 0 tools
 * yields none (honest, never a phantom def).
 */
export function buildMcpToolDefs(sources: readonly McpServerToolSource[]): ToolDef[] {
  const out: ToolDef[] = [];
  const claimed = new Map<string, string>();
  for (const source of sources ?? []) {
    const server = source?.server;
    if (!server || !Array.isArray(source.tools)) continue;
    const serverSlug = slugMcpToolName(server.name);
    for (const tool of source.tools) {
      const toolName = String(tool?.name ?? '');
      if (!toolName) continue;
      const name = `mcp__${serverSlug}__${slugMcpToolName(toolName)}`;
      const prior = claimed.get(name);
      if (prior) {
        // Two distinct tools collapsing to one agent name is the ONLY case
        // where a def cannot be emitted. Say so loudly — never silent.
        console.warn(
          `[mcp] "${server.name}/${toolName}" maps to agent name "${name}" already claimed by "${prior}". ` +
            'The second tool cannot be addressed — rename one of them on the server.',
        );
        continue;
      }
      claimed.set(name, `${server.name}/${toolName}`);
      out.push({
        name,
        description: `[MCP · ${server.name}] ${tool.description || toolName}`,
        parameters: jsonSchemaObject(tool.inputSchema),
        kind: 'mcp',
        mcpServerName: server.name,
        mcpToolName: toolName,
      });
    }
  }
  return out;
}

/** Honest disconnection error for a def whose server has vanished. */
export function mcpDisconnectedError(serverName: string): string {
  return `MCP server "${serverName}" is not connected. Reconnect it in Settings → MCP, then retry.`;
}
